package com.flymaccin.bookwriter;
import android.content.Context;import android.webkit.JavascriptInterface;import android.webkit.WebView;import org.json.JSONArray;import org.json.JSONObject;import java.io.*;import java.net.HttpURLConnection;import java.net.URL;import java.nio.charset.StandardCharsets;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;
public class BookwriterBridge{private final WebView webView;private final ExecutorService executor=Executors.newSingleThreadExecutor();private final SecureKeyStore secure;private volatile HttpURLConnection active;BookwriterBridge(Context c,WebView w){webView=w;secure=new SecureKeyStore(c);}@JavascriptInterface public void setOpenAIKey(String key){try{secure.save(key.trim());callback("settings",true,"OpenAI key saved securely on this device.");}catch(Exception e){callback("settings",false,e.getMessage());}}@JavascriptInterface public boolean hasOpenAIKey(){try{return!secure.load().isEmpty();}catch(Exception e){return false;}}@JavascriptInterface public void clearOpenAIKey(){secure.clear();}@JavascriptInterface public void cancelGeneration(){HttpURLConnection c=active;if(c!=null)c.disconnect();active=null;}@JavascriptInterface public void generate(String id,String prompt,String model){executor.execute(()->{try{String key=secure.load();if(key.isEmpty())throw new IllegalStateException("Configure your OpenAI API key in Settings first.");String chosen=(model==null||model.trim().isEmpty())?"gpt-5.6-terra":model.trim();HttpURLConnection c=(HttpURLConnection)new URL("https://api.openai.com/v1/responses").openConnection();active=c;c.setRequestMethod("POST");c.setConnectTimeout(30000);c.setReadTimeout(180000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Authorization","Bearer "+key);JSONObject body=new JSONObject().put("model",chosen).put("input",prompt).put("store",false);try(OutputStream os=c.getOutputStream()){os.write(body.toString().getBytes(StandardCharsets.UTF_8));}int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();String raw=readAll(in);if(code<200||code>=300)throw new IllegalStateException(error(code,raw));String text=extract(new JSONObject(raw));if(text.isEmpty())throw new IllegalStateException("OpenAI returned no text output.");callback(id,true,text);}catch(Throwable t){callback(id,false,t.getMessage()==null?"Generation failed":t.getMessage());}finally{if(active!=null)active.disconnect();active=null;}});}
private static String extract(JSONObject j){StringBuilder out=new StringBuilder();JSONArray a=j.optJSONArray("output");if(a==null)return"";for(int i=0;i<a.length();i++){JSONObject item=a.optJSONObject(i);if(item==null)continue;JSONArray c=item.optJSONArray("content");if(c==null)continue;for(int k=0;k<c.length();k++){JSONObject p=c.optJSONObject(k);if(p!=null&&"output_text".equals(p.optString("type"))){String t=p.optString("text","");if(!t.isEmpty()){if(out.length()>0)out.append("\n\n");out.append(t);}}}}return out.toString().trim();}private static String readAll(InputStream in)throws IOException{if(in==null)return"";try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){StringBuilder b=new StringBuilder();String l;while((l=r.readLine())!=null)b.append(l).append('\n');return b.toString();}}private static String error(int c,String raw){try{JSONObject e=new JSONObject(raw).optJSONObject("error");if(e!=null&&!e.optString("message","").isEmpty())return"OpenAI request failed ("+c+"): "+e.optString("message");}catch(Exception ignored){}if(c==401)return"OpenAI authentication failed (401). Check the API key.";if(c==403)return"OpenAI access refused (403). Check project/model permissions.";if(c==429)return"OpenAI rate or quota limit reached (429). Your draft is preserved.";if(c>=500)return"OpenAI service error ("+c+"). Your draft is preserved.";return"OpenAI request failed ("+c+").";}private void callback(String id,boolean ok,String payload){String js="window.__fmeAndroidResult&&window.__fmeAndroidResult("+JSONObject.quote(id)+","+ok+","+JSONObject.quote(payload)+");";webView.post(()->webView.evaluateJavascript(js,null));}}
